quests[75360] = { id = 75360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subterrax" }
quests[75362] = { id = 75362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zephalokristallisation", description = "Na, hallo!\n\nHabt Ihr diese Schnecken in der Zaralekhöhle gesehen, denen Kristalle aus der Schale wachsen? \n\nWenn sie zermahlen und der richtigen Schleimlösung beigemischt werden, lässt sich aus diesen Kristallen eine Paste herstellen, mit denen wir unseren Edelsteinen einen ganz besonderen Glanz verpassen können! Bringt einige zu meiner guten Freundin Fanilly, dann erzählt sie Euch garantiert mehr über Juwelierskunst, als Ihr je wissen wolltet!", sourceObjective = "Sammelt 10 Spitzschneckenkristalle und bringt sie zu Fanilly in Loamm.", progress = "Wisst Ihr, für uns ist es sehr wichtig, dass Edelsteine gut poliert sind... Andernfalls fällt es uns schwer, ihren Glanz überhaupt erst zu sehen!", completion = "Oh ja, das sollte reichen! Und jetzt schaut her, einfach zusammen mit dem Schleim zermahlen, auf den Edelstein auftragen und dann polieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[75363] = { id = 75363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenschinderstaub", description = "Oh, ich habe gerade einen weiteren Brief von meiner guten Freundin Neblie bekommen. Sie ist auf der Suche nach interessanten Zutaten für ihre duftigen Gebräue!\n\nVor einer Weile haben die Sippenwachen einen Tiefenschinder in der Nähe von Loamm erlegt. Als er starb, verstreute er einen seltsamen Staub. Der hatte ein einzigartiges Aroma, und Neblie würde sicher gern mit so etwas experimentieren!\n\nKönntet Ihr ein wenig von den Tiefenschindern in der Nähe von Loamm sammeln und es dann zu Frau Neblie bringen? Damit würdet Ihr uns auch einen Gefallen tun!", sourceObjective = "Sammelt 10 Tiefenschinderstaub und bringt ihn zu Neblie in Loamm.", progress = "Was für ein mysteriöses muffiges Aroma... Der markante Duft des Todes wird von der Sanftheit von Erde begleitet.", completion = "Oh ja, das ist wunderbar! Könnt Ihr es mit Eurer Nase riechen? Sehr duftig!", sourceObjectiveStatus = "unverified-source-field" }
quests[75364] = { id = 75364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutnacht" }
quests[75366] = { id = 75366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viridiankönig" }
quests[75367] = { id = 75367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Obsidianrast", description = "Es grenzt an ein Wunder, dass dieser Außenposten nach Neltharions... Verschwinden solange überlebt hat.\n\nSeit Wochen berichten Späher von erhöhter Djaradinaktivität in dem Gebiet. Sie bauen eine Armee auf und werden immer aggressiver, wenn es darum geht, ihr Territorium zu erweitern.\n\nWir müssen jede erdenkliche Vorsichtsmaßnahme ergreifen, um die Motivationen des Feindes zu verstehen.", sourceObjective = "Sammelt Informationen und Ressourcen an der Obsidianrast.", progress = "Wir alle leben in harten Zeiten.", completion = "Wir müssen besprechen, was Ihr in Erfahrung bringen konntet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75368] = { id = 75368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine und Schuppen", description = "Ich bin sicher, Euch sind auf Euren Abenteuern einige der fiesen Bestien begegnet, die hier in Zaralek ihr Unwesen treiben! Habt Ihr schon diese Felsvipern gesehen? \n\nDie sind mit Schuppen und Steinen überzogen! Und haben riesige Zähne!\n\nHerr Garram hat eine Belohnung für alle angeboten, die mutig genug sind, ihm ein paar ihrer Häute zu bringen! Ich bin sicher, das lohnt sich für Euch!", sourceObjective = "Sammelt 10 schuppige Steinbälge von Felsvipern in der Zaralekhöhle.", progress = "Habt Ihr die Bälge schon gesammelt? Diese Schlangen können etwas furchteinflößend sein, doch ein {class} wie Ihr sollte damit keine Probleme haben!", completion = "Wunderbar! Die sind perfekt. Schaut, wie hart und scharf die Schuppen sind!\n\nDanke für Eure Hilfe! Ich werde Kayann wissen lassen, ob ich noch etwas brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[75369] = { id = 75369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nutzt Eure Münze!", description = "Nutzt die Münze bei dem Warcraft Rumble-Automaten da drüben." }
quests[75370] = { id = 75370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räucherduftwerk" }
quests[75371] = { id = 75371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faszinierende Fungi", description = "Ah, <Oberländer/Oberländerin>! Kann ich Euch um Hilfe bitten?\n\nDie Höhle dort unten ist voller Pilze, die für allerlei Dinge nützlich sind! Frau Neblie braucht Hilfe dabei, diese für ihre Alchemie-Experimente zu sammeln.\n\nSie sagt, die Gelkappenpilze sondern klebrige Sporen ab, aus denen sie eine Salbe für schmerzende Gelenke und Fußballen herstellen kann! Ich stehe den ganzen Tag auf diesen harten Steinen, da kann ich so etwas gebrauchen!\n\nWenn Ihr ihr ein paar Sporen bringt, wird sie Euch sicher angemessen belohnen!", sourceObjective = "Sammelt 10 Gelkappensporen.", progress = "Habt Ihr die Sporen gesammelt? Ich kann es kaum erwarten, sie in die Finger zu bekommen!", completion = "Das sind unglaublich klebrige Sporen! Danke, {name}! \n\nWenn Ihr Kayann das nächste Mal seht, sagt ihm, er bekommt seine Salbe bald... Und kostenlose Sonnencreme noch dazu! Ich habe keine Ahnung, wie er es da oben den ganzen Tag aushält!", sourceObjectiveStatus = "unverified-source-field" }
quests[75372] = { id = 75372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austrieb", description = "Vertreibt diese Störenfriede aus unseren Landen, {name}!\n\nFür Imbu! Für das Azurblaue Gebirge!", sourceObjective = "Tötet die Djaradin und Primalisten, die das Azurblaue Gebirge angreifen.", progress = "Prächtig.", completion = "Das werden sie so schnell nicht vergessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75373] = { id = 75373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansturm der Ottukbrigade", description = "Pah! Sie verstecken sich hinter ihren Barrikaden in der Hoffnung, dass sie das vor unserer Vergeltung schützt.\n\nMacht uns den Weg frei, dann werden wir diese Feiglinge niederreiten!", sourceObjective = "Zerstört Barrikaden der Djaradin.", completion = "Ihr werdet unsere Speere zu schmecken bekommen, Fyrakk!", sourceObjectiveStatus = "unverified-source-field" }
quests[75374] = { id = 75374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt das Gebirge", description = "Die Djaradin haben ohne Vorwarnung zugeschlagen, {name}. Unsere Leute sind fähige Kämpfer, doch in so einer Schlacht kommt niemand unbeschadet davon.\n\nHelft bitte mit den Verwundeten. Viele sind hinter den feindlichen Linien gefangen und schaffen es in ihrem Zustand nicht allein wieder zurück.", sourceObjective = "Heilt 6 bärbeißige Fischer mit den zur Verfügung gestellten Bandagen oder Euren eigenen Fähigkeiten.", completion = "Gerettete Leben sind immer eine Feier wert. Wir haben so schon genug verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[75375] = { id = 75375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennendes Eis", description = "Was auch immer die Djaradin für eine Magie hier anwenden, setzt das Eis da draußen in Brand, {name}.\n\nWir dürfen nicht zulassen, dass es sich über den Rest des Gebirges ausbreitet. Es muss aufgehalten werden, bevor die Flammen alles verzehren.\n\nSammelt auf Eurem Drachen so viel Wasser, wie Ihr könnt, und ertränkt die Flammen. Hoffentlich reicht das, um sie zu löschen.", sourceObjective = "Löscht Feuer im Lager der Djaradin.", completion = "Danke, {name}. Wenigstens konnten wir den Schaden begrenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75376] = { id = 75376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchströmen, wiederverwenden und wiederverwerten", description = "Wenn Fyrakk gewillt ist, auf der Suche nach diesen Materialien offen auf der Oberfläche anzugreifen, müssen sie wichtig für seine Pläne sein.\n\nNehmt, was Ihr könnt. Es muss einen Weg geben, sie zu unseren Gunsten zu verwenden.", sourceObjective = "Holt Infusionsvorräte von Fyrakks Streitkräften zurück.", progress = "Wir stärken uns selbst, wenn wir unseren Feinden wichtige Ressourcen verweigern.", completion = "Hervorragende Arbeit, {name}. Die hätten sie nicht ohne Weiteres aufgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75377] = { id = 75377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barrikade aufrechterhalten", description = "Das ist alles, was ich tun kann, um den Schild gegen den Beschuss dieser Schattenflammendrachen aufrechtzuerhalten.\n\nGebietet ihnen Einhalt, bevor wir hier komplett festgenagelt werden.", sourceObjective = "Tötet Urnachtflammen oder holt sie mit 'Wirbelnder Ansturm' aus der Luft.", completion = "Ausgezeichnete Arbeit. Vielleicht komme ich vor der nächsten Katastrophe sogar mal zum Durchatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75378] = { id = 75378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eschentalecke", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75379] = { id = 75379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eschentalecke - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75380] = { id = 75380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eschentalecke - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75382] = { id = 75382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalkampf", description = "Die Primalisten kanalisieren elementare Kräfte durch diese Portale, wodurch sie ihr gesamtes Unterfangen mit Energie versorgen und die Produktion dieser durchströmten Barren beschleunigen.\n\nBald sind sie stabil genug, um ihre elementaren Verbündeten durchzulassen und ihre Position zu verstärken.\n\nWir müssen sie versiegeln, bevor es dazu kommt, sonst könnte sich die Schlacht zu ihren Gunsten wenden.\n\nNehmt diesen Fokus und stört die schützenden Runen ihrer Portale, anschließend können wir von oben zuschlagen. Nur gemeinsam haben wir eine Chance.", sourceObjective = "Schwächt die Verteidigung der Portale.", progress = "Gemeinsam, {class}.", completion = "Ausgezeichnet. Das sollte die Situation zumindest stabilisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[75383] = { id = 75383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterschlupf unter Wasser", description = "Das sollte ein friedlicher Ruhesitz werden, keine Kriegszone!\n\nSchnappt Euch eines der Totems, die die Schamanen haben liegen lassen und löscht diese Feuer, bevor meine Träume von einer hübschen Angelzuflucht buchstäblich in Rauch und Flammen aufgehen!", sourceObjective = "Verwendet ein Wassertotem, um die Feuer in Grimmhauers Unterschlupf zu löschen.", progress = "Wer brennt eine Eisangelhütte nieder?", completion = "Gute Arbeit, {race}. Vielleicht bekomme ich endlich einen Nachmittag für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[75384] = { id = 75384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammutschulden", description = "Mich töten zu wollen, das kann ich noch verzeihen, aber meinen Unterschlupf anzugreifen? Jetzt wird es persönlich.\n\nDie Djaradin beladen ihre Mammuts mit so vielen Barren, wie sie tragen können, um sie zurück zu ihrem geliebten Fyrakk zu bringen.\n\nSchnappt Euch eines davon und bringt es her, mit Ladung und allem Drum und Dran.", sourceObjective = "Steigt auf ein überladenes Mammut und bringt es hinter Eure Linien.", progress = "Worauf wartet Ihr noch? Dass es taut?", completion = "Das ist doch mal eine Aussage!", sourceObjectiveStatus = "unverified-source-field" }
quests[75385] = { id = 75385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotardurchquerung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75386] = { id = 75386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotardurchquerung - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75387] = { id = 75387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotardurchquerung - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75388] = { id = 75388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Azurblaue Gewölbe", description = "Es gibt ein Problem im Azurblauen Gewölbe, {name}.\n\nUnter den Azurarchiven ruht das Azurblaue Gewölbe. Sindragosa hat so manche wichtige und gefährliche magische Kuriosität darin eingelagert.\n\nJetzt ist eine große Gruppe von Splitterflammen ins Gewölbe eingebrochen, um dessen Geheimnisse an sich zu reißen.\n\nIhr müsst da rein und sie aufhalten!", sourceObjective = "Haltet die Splitterflammen im Azurblauen Gewölbe auf.", progress = "Passt im Gewölbe auf Euch auf.", completion = "Danke für Eure Hilfe im Gewölbe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75390] = { id = 75390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertikale Anomalie" }
