quests[75398] = { id = 75398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer an der Küste des Erwachens.", completion = "Ehrt die Flamme der Küste des Erwachens.", sourceObjectiveStatus = "unverified-source-field" }
quests[75407] = { id = 75407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am seidenen Faden", description = "Hallöchen! Ihr seid doch <ein Schneider/eineSchneiderin>, oder? Dann kennt Ihr Euch bestimmt mit Seide aus!\n\nHerr Rossmar unten in Loamm weiß, wie man aus den Kokons der Tiefenlichtmotten besondere Seide herstellt, könnte aber beim Sammeln etwas Hilfe brauchen! \n\nIhr solltet bei den Pilzen nahe Glimmerogg welche finden. Er wird Euch sicher angemessen entlohnen!", sourceObjective = "Sammelt 10 Tiefenlichtkokonfasern in der Zaralekhöhle.", progress = "Heda, Oberländer! Habt Ihr schon diese Kokons?", completion = "Die sehen klasse aus! Danke, {name}!\n\nJetzt müssen wir sie nur noch kochen und Fäden daraus machen. Oh, die geben einen UMWERFEND stinkigen Gestank von sich, wenn man sie kocht.\n\nWas meint Ihr? Ihr müsst schnell los? Oh, na gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[75408] = { id = 75408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An alle Dracthyr!", description = "<Dieses Flugblatt ist mit einladenden Zeichnungen von Dracthyr illustriert, die zeigen, wie sie essen, sparren und Spaß haben.>\n\nAn alle Dracthyr!\n\nFühlt Ihr Euch nach all den Ereignissen im Untergrund etwas verloren? Wollt Ihr Euch mit Euren Hortgefährten zusammenfinden? Braucht Ihr einfach jemanden zum Reden?\n\nDann schließt Euch uns im Weyrnruh an. Wir haben Essen, Spaß und Kameradschaft! ALLE Dracthyr sind willkommen!", sourceObjective = "Begebt Euch zu der Feier in Weyrnruh in Valdrakken.", completion = "Alle sind müde, so viel steht fest. Doch es ist diese Form von Gemeinsamkeit, die uns dabei helfen wird, zu heilen.\n\nWarum schaut Ihr Euch nicht um und sprecht mit ein paar {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[75409] = { id = 75409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desolacedrift", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
