quests[75414] = { id = 75414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Schluchtsturzflug - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75417] = { id = 75417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbol der Hoffnung", description = "Ebyssian, Sabellian und Furorion haben sich geeinigt, wer die Führung übernehmen sollte, und stellen eine geeinte Front dar. Alle drei haben auch Euren Beitrag und Eure unersetzliche Hilfe in der Zaralekhöhle hervorgehoben. Sie waren sich offenbar einig, dass Ihr entscheidend für ihren Erfolg wart.\n\nEin hohes Lob - und wohl verdient.\n\nBitte bleibt noch etwas länger. Die anderen Aspekte und ich haben Wichtiges zu besprechen, und ich denke, Ihr solltet dafür auch anwesend sein.", sourceObjective = "Sprecht mit Alexstrasza.", completion = "Es gibt noch immer viel zu tun, aber die fünf vereinten Aspekte zu sehen, erfüllt mein Herz mit Hoffnung... und Freude.\n\nHabt Dank. Euer Anteil daran wird nie vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[75419] = { id = 75419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitterflammen", description = "War dieser Ort hier Neltharions Hort? Da ist es kein Wunder, dass Sarkareth danach gesucht hat.\n\nJeder Winkel ist voll von Neltharions \"Schätzen\".\n\nMan kann nur erahnen, was Sarkareth alles hier zusammengetragen hat.\n\nBleibt in der Nähe!", sourceObjective = "Findet Sarkareth.", completion = "Ich wollte nicht gegen Dezran kämpfen. Sarkareths starke Persönlichkeit und manipulativen Worte lassen seine Anhänger selbst seinen wildesten Anweisungen folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75437] = { id = 75437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenhauerkreisel", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
