quests[75440] = { id = 75440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfschnabel sättigen", description = "Sheridon Hastle war unser Flugmeister und Scharfschnabels Reiter. Nach seinem Tod lässt sie niemanden an sich heran.\n\n<Narvra hält sich die Seite vor Schmerzen.>\n\nAuch nicht zum Füttern. Rupert hat es versucht, aber... sie lässt es nicht zu.\n\nDer Rest von uns ist zu verwundet und kann sich nicht bewegen... Ich mache mir Sorgen um sie.\n\nKönnt Ihr es versuchen? Ein neues Gesicht könnte sie vielleicht überreden. Ihr Futtersack ist beim Zelt.\n\nUnd... wenn es Euch gelingt, sie zu füttern, dann lässt sie Euch vielleicht auch auf sich reiten.", sourceObjective = "Füttert Scharfschnabel im Drachenschuppenlager in der Zaralekhöhle.", progress = "<Scharfschnabel sieht Euch traurig an.>", completion = "<Scharfschnabel nimmt vorsichtig das Futter von Euch an.\n\nNach ein paar Happen sieht sie Euch in die Augen, breitet die Flügel aus und schüttelt sie.\n\nIhr habt das Gefühl, dass Ihr sie reiten dürftet, wenn Ihr wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75441] = { id = 75441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müffelnde Mixtur" }
quests[75444] = { id = 75444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalerkundung: Die Verbotene Insel", description = "<Noch ein Besuch von Charly, noch ein Ruf von der Drachenschuppenexpedition.\n\nAnscheinend hat Thaelin Schwarzamboss wieder einmal etwas Interessantes für Euch.>", sourceObjective = "Trefft Thaelin Schwarzamboss beim Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Gut, Euch wiederzusehen, {name}.\n\nDie Inseln bieten offenbar endlose Möglichkeiten für Abenteuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[75450] = { id = 75450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seismische Zeremonie" }
