quests[75455] = { id = 75455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwörung der Flammen" }
quests[75456] = { id = 75456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues von unter der Erde", description = "Vor meiner Ankunft hat man mich darüber informiert, dass die Lebensbinderin unsere Hilfe braucht. Sie hat Neuigkeiten über die Inkarnationen und verlangt unsere Anwesenheit am Sitz der Aspekte.\n\nWas Glutthal anbelangt: Im Moment können wir nur sehr wenig tun. Wir lassen sie am Besten in Ruhe nachdenken, damit sie ihre Gedanken ordnen kann.", sourceObjective = "Trefft Alexstrasza am Sitz der Aspekte in Valdrakken.", completion = "Die Aspekte haben sich versammelt. Lassen wir sie nicht warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[75459] = { id = 75459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandheiße Buddeleien" }
quests[75461] = { id = 75461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmaklauenmatriarchin" }
quests[75462] = { id = 75462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäuserettung", description = "Ich fühle mich schlecht wegen dem, was ich unter Malrogg getan habe. Er war einfach so groß und furchteinflößend, und ich hatte das Gefühl, keine Wahl zu haben...\n\n<Agrul schüttelt langsam den Kopf.>\n\nKeine Ausreden mehr. Wir müssen diese Schnüffelmaus zurück nach Hause zu Yarren bringen.\n\nIch war nie stark genug, um mich alleine mit Malrogg anzulegen. Aber Ihr... Ihr könnt Persii retten.", sourceObjective = "Tötet Malrogg.", progress = "Habt Ihr den Drogbar gefunden?", completion = "Ich kann Euch beiden nicht genug danken, dass Ihr Persii gerettet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[75463] = { id = 75463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faden der Tausend Nadeln", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
