quests[75466] = { id = 75466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verirrte zeitverlorene Wikinger", description = "Vor einer Weile sind ein paar ungehobelte Kerle aus einem Temporalportal gestolpert. Bevor ich einen Zeitwanderer holen konnte, um sie nach Hause zu bringen, entschieden sie sich, nach Valdrakken zu reisen.\n\nWürdet Ihr Olaf, Baelog und Eric suchen und sie hierher zurückbringen, bevor sie zu viel Unordnung machen?", sourceObjective = "Überzeugt die verlorenen Wikinger, zur Grenze des Äons zurückzukehren.", progress = "Habt Ihr sie gefunden?", completion = "Die drei hatten ihren Spaß, aber es wurde höchste Zeit, dass sie zurückgehen, wo sie hingehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[75468] = { id = 75468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralasschuttstreifzug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
