quests[75493] = { id = 75493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Flussbetts", description = "Ich hoffe, Ihr habt Eure Stiefel dabei, dieses Mal wird es nämlich nass!\n\nDieser Fluss trägt Artefakte von den Bergen herab, und sie werden hier im Schlick angespült. Die Zentauren haben hier über die Jahre hinweg eine ganze Menge gefunden.\n\nWir sind hier, um uns das genauer anzusehen und herauszufinden, ob unter der Oberfläche etwas Interessantes wartet.", sourceObjective = "Sprecht mit Roska, um mit der Ausgrabung zu beginnen, und grabt dann Artefakte aus dem Flussbett aus.", completion = "<Roska entfährt ein leises Pfeifen.>\n\nNa, so etwas sieht man nicht jeden Tag. Holen wir sie dort raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[75494] = { id = 75494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbe bekennen" }
quests[75497] = { id = 75497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Katalysators", sourceObjective = "Sprecht mit Antuka in Tyrhold.", completion = "Jede Woche gewährt Euch der Katalysator genug Macht, um einen Ausrüstungsgegenstand zu verzaubern.\n\nHüter Tyr muss über uns wachen. Wo auch immer er sein mag, das kann kein Zufall sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[75506] = { id = 75506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenflammenwappen", description = "Jetzt, da Ihr einen Vorgeschmack auf Macht bekommen habt, kann der wahre Spaß beginnen.\n\nMit Flugsteinen allein kommt Ihr nicht besonders weit. Wir haben vier verschiedene Stufen an Schattenflammenwappen entdeckt, die benötigt werden, um noch mächtigere Ausrüstung zu ermächtigen.\n\nFünfzehn Bruchstücke können zu einem kompletten Wappen ihrer Stufe vereint werden. Genau wie Flugsteine können auch Bruchstücke auf den Dracheninseln erhalten werden. Je gefährlicher die Aktivität, desto mächtiger die Bruchstücke.\n\nUnd sucht Spinsoa draußen auf, wenn Ihr Bruchstücke benötigt. Er kann Euch welche verkaufen.", sourceObjective = "Sucht Spinsoa auf und erschafft ein Schattenflammenwappen, indem Ihr 15 Schattenflammenwappenbruchstücke der gleichen Stufe kombiniert.", completion = "Perfekt. Aufwertungsspezialisten können immer feststellen, ob für Eure Aufwertung Wappen benötigt werden.\n\nUnd wenn wir schon beim Thema Macht sind, hier, nehmt dieses Schmuckstück! Mir wurde aufgetragen, sie als Willkommensgeschenke an Loamms Neuankömmlinge zu verteilen.\n\nWir können das Schmuckstück in unserer nächsten Lektion einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75507] = { id = 75507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem neuesten Stand", description = "Jetzt, da Ihr die Grundlagen kennt, fällt es Euch vielleicht leichter, niedrigstufigere Ausrüstung aufzuwerten.\n\nNehmt das Räuchergefäß der Freundschaft zum Beispiel. Wenn Ihr in der Vergangenheit mächtigere Schmuckstücke erhalten habt, kostet es uns weniger Ressourcen, dieses Schmuckstück aufzuwerten.\n\nEuch wird auffallen, dass Ihr weniger Flugstein benötigt! Und Wappen sind auch nicht erforderlich.\n\nNa los, versucht, das Schmuckstück oder einen anderen niedrigstufigen Ausrüstungsgegenstand von Euch aufzuwerten. Falls Ihr noch ein Schmuckstück braucht, Gastwirtin Floressa verkauft welche.", sourceObjective = "Wertet das Räuchergefäß der Freundschaft oder einen Ausrüstungsgegenstand auf Forscherstufe mit Flugsteinen auf.", completion = "Mit diesem Wissen habt Ihr meinen Segen, voranzuschreiten und die Macht zu erreichen, von der Ihr stets geträumt habt. Wenn Ihr je eine Auffrischung braucht, könnt Ihr einfach mit mir reden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75511] = { id = 75511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75516] = { id = 75516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolgreiche Interventionen" }
quests[75517] = { id = 75517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleichen und schnüffeln" }
quests[75518] = { id = 75518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leiche an den Ufern", description = "<Der Leichnam dieser Zentaurenfrau ist in einem überraschenden Zustand.\n\nIhre Kleidung ist in einem Euch unbekannten Stil gehalten, und ihre Haut ist mit komplizierten Tattoos bedeckt.\n\nIhr Körper ist intakt, also kann sie noch nicht lange tot sein... oder? Die Umweltbedingungen hier sind vielleicht dafür verantwortlich, dass er so gut erhalten geblieben ist.\n\nRoska wird sich das ansehen wollen!>", sourceObjective = "Sprecht mit Roska, um damit zu beginnen, den Zentaurenleichnam vorsichtig auszugraben.", completion = "Sieh sich einer das an! Ich wette, dieses arme Ding war seit Hunderten von Jahren unter diesem Schlick begraben, wenn nicht länger.\n\nMoore und Flussbette wie dieses erhalten oft, was darin zurückbleibt.\n\nAber jetzt, wo sie befreit ist, können wir mehr darüber herausfinden, wer sie war und wie sie hierherkam.", sourceObjectiveStatus = "unverified-source-field" }
quests[75519] = { id = 75519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die lange Jagd", description = "<Dori'thur blickt Euch leise schwebend mit aufmerksamen, erwartungsvollen Augen an.\n\nDie noble Eule bietet Euch in ihren Krallen einen magieerfüllten Kristall an. Ihr könnt eine Botschaft in dem Kristall spüren.>", sourceObjective = "Seht Euch die Botschaft an.", completion = "<Dori'thur zwinkert wissend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75528] = { id = 75528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung für Tester, um Zaralek zu betreten", description = "Seid gegrüßt!\n\nAuch wenn Zaraleks Geschichte sich erst noch entfaltet, gibt es vieles in der Höhle zu sehen! Begebt Euch nach Loamm, zur Heimat der Niffen.", sourceObjective = "Betretet die Zaralekhöhle über Iridikrons Schachzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[75538] = { id = 75538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Start der Wichteleien", description = "Finsterste Grüße, {race}. Ähem, ja. Ja! Finsterste Grüße, so ist es.\n\n<Der schlaksige Mann scheint sich plötzlich daran zu erinnern, wo er ist.>\n\nIm Namen meines Schutzpatrons lade ich Euch ein, zum Dunkelmond-Jahrmarkt zu reisen. Der Jahrmarkt! Wer liebt ihn nicht? Ja. Ja!\n\nÄhem.\n\nSie verlangt nach Eurer Anwesenheit, das tut sie! Unsere Dame des Mitternachtsmonds. Die Dame der Dunkelheit! Die Mutter der Krähen...\n\n...Madame Schatten.", sourceObjective = "Reist zum Dunkelmond-Jahrmarkt.", completion = "Ihr seid... kleiner, als ich in Erinnerung hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[75539] = { id = 75539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tückische Sachen sind unterwegs", sourceObjective = "Redet mit den neu eingetroffenen Hexenmeistern auf dem Dunkelmond-Jahrmarkt.", completion = "Nur ein oder zwei Paar kalte Füße, hm? \n\n<Madame Schatten lacht leiste.>\n\nAusgezeichnet.\n\nDa wir jetzt wissen, wer hier sein will, ist es Zeit, zu ermitteln, wer es verdient, hier zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[75540] = { id = 75540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hermetische Versicherung", sourceObjective = "Benutzt Madame Schattens Seelenstein bei bereitwilligen Initianden auf dem Dunkelmond-Jahrmarkt.", completion = "Köstlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[75541] = { id = 75541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zögerlichen", description = "Hm.\n\nEs gibt einen, der zu uns gehörte, aber er ist nicht hier.\n\nDer Draenei.\n\n<Madame Schatten atmet ein.>\n\nIch kann das Licht um ihn spüren. Geht, sorgt dafür, dass er sich uns wieder anschließt.\n\nEs gibt viel Arbeit zu erledigen.", sourceObjective = "Sprecht mit Initiand Oman auf dem Dunkelmond-Jahrmarkt.", progress = "Dieser Anblick erinnert mich an... viele Dinge.", completion = "Nun wollen wir unseren geheimnisvollen Patron zufriedenstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[75542] = { id = 75542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüche & Kultisten", description = "Der Weizen wurde von der Spreu getrennt. Nun beginnt das Vergnügen.\n\nIch habe einen aufregenden... Ausflug... für unsere Schüler geplant. Aber sie sind noch nicht bereit. Nehmt mein Grimoire und lasst die Pandaren, Zandalari und Tauren sich an Flüchen versuchen.\n\nIch habe einige ungeladene Gäste am Rand des Jahrmarkts herumlungern sehen. Sie sollten ausgezeichnete, wenn auch kaum bereitwillige Versuchsobjekte abgeben.\n\nOman wird die Ehre haben, die Gruppe ins Feld zu beschwören, und ich werde ihm entsprechenden Anweisungen geben.", sourceObjective = "Lehrt die Initianden Flüche aus Madame Schattens Grimoire auf dem Dunkelmond-Jahrmarkt.", completion = "Es hat funktioniert! Dieses Grimoire von Madame Schatten ist wirklich mächtig...\n\nIch hoffe, ich habe Euch nicht erschreckt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75543] = { id = 75543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Riten wider Willen", description = "<Ihr hört von der anderen Seite des Portals gedämpfte Schreie.>", sourceObjective = "Geht durch das dämonische Tor und helft den Initianden.", completion = "Die anderen... ihre Seelensteine...\n\nIch sah ein grünes Flackern in ihren Augen als sie fielen, einer nach dem anderen. Es war, als sei ihnen die Essenz ihrer Seelen entzogen worden.\n\nSie haben Besseres verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[75544] = { id = 75544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Rache grüne Flammen schlägt", sourceObjective = "Stellt Madame Schatten in den Verwüsteten Landen.", completion = "Diese Seelensteine... die anderen {class}.\n\n\n\nAls ich mich entschloss, diesen Weg zu gehen, wusste ich, dass es Konsequenzen geben würde. Dass ich einen Teil meiner selbst opfern müsste. Einen Teil davon, wie mein Volk mich sieht.\n\nAber die eigene Seele zerreißen zu spüren... Für was? Kleinliche Rache?\n\nDas ist wahrlich ein Schicksal, dass schlimmer ist als alles, was ich mir selbst aufgebürdet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75569] = { id = 75569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenschmiede in Schwarz", description = "Die schwarzen Drachkin im Norden der Zaralekhöhle sollen begabte Schmiede sein.\n\nSie behaupten gerne, dass es etwas mit ihrer \"Herrschaft über das Erdreich\" zu tun hätte, aber ich bezweifle, dass sie den Niffen das Wasser reichen können, wenn es ums Graben geht!\n\nÜber die Ergebnisse lässt sich allerdings nicht streiten. Besorgt ein paar Exemplare und bringt sie Flammenmeister Crubus, damit er ihre Techniken studieren kann.", sourceObjective = "Sammelt 8 geschwärzte Platten.", progress = "Ich frage mich, ob ich einen ihrer Helme als Badewanne verwenden könnte...", completion = "Die Verarbeitung ist makellos, aber würde es sie umbringen, etwas herzustellen, das eine andere Farbe als Schwarz hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[75573] = { id = 75573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Magie der Bürokratie", description = "Wisst Ihr, wer sich gerne selbst reden hört, Bürokratie liebt und verzaubert seine eigenen Aufzeichnungen? Drachen!\n\nSchaut Euch in der alten Schwarzdrachenfestung nördlich von Loamm um. Dort sollte es allerlei magische Verordnungen, Proklamationen und Einkaufslisten geben!\n\nBringt all Eure Funde zu Scridorsa der Metz in Loamm. Ich bin sicher, ihr wird neuer, stark verzauberter Lesestoff gefallen!", sourceObjective = "Sammelt 10 energieerfüllte Proklamationen.", progress = "Warum einfach, wenn es auch magisch geht, nicht wahr?", completion = "<Scridorsa blättert durch die Dokumente.>\n\n\"Durch meine Hand...\", \"Der Wille des Erdwächters...\", \"Auf mein Geheiß...\". Das klingt jedenfalls nach einem Drachen!\n\nDie sollten interessant zu studieren sein, vielleicht sind sie sogar spannende Lektüre.", sourceObjectiveStatus = "unverified-source-field" }
quests[75575] = { id = 75575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ballistenteile", description = "Diese Djaradin mögen wie Grobiane riechen, aber ihr Ingenieurstrupp muss auf dem höchsten Niveau sein, wenn sie eine Balliste nach der anderen raushauen! Und die Dinger sind dabei sogar stark genug, um Drachen gefährlich zu werden!\n\nNordöstlich von Loamm prügeln sie sich andauernd mit schwarzen Drachen. Auf den Schlachtfeldern sollten mehr als genug Ersatzteile zu finden sein. Oder zumindest leicht benutzte, mäßig brennende Teile!\n\nBringt sie alle zurück nach Loamm! Ein paar Brandspuren halten unsere besten Niffeneure nicht davon ab, sie zu untersuchen.", sourceObjective = "Sammelt 10 Ballistenteile.", progress = "Was sie wohl für den Drall verwenden?", completion = "Interessant, das ist deutlich mehr Knochen als ich bei der Belastung erwartet hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[75576] = { id = 75576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion des Grimmigen Säufers" }
quests[75598] = { id = 75598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Schnecke, große Schleimspuren", description = "Hmm. Habt Ihr je eine Schnecke geritten?\n\nIch habe Generationen von Rennschneckenchampions trainiert, aber jetzt ist mir der schwerste Fall aller Zeiten begegnet. Er ist schlicht und einfach zu vercrokt groß. Darf direkt mal nicht antreten.\n\nAber es wäre eine Schande, so ein tolles Exemplar in einem Eimer zu lassen. Wenn Ihr mir dabei helft, Schleimer zu dem Rennchampion zu machen, der in ihm steckt, überlasse ich ihn Euch!", sourceObjective = "Stellt Euch Schleimer vor.", completion = "Ja schneck' mich doch am... Ich war noch nie so stolz. Ihr habt es geschafft.\n\nNicht viele haben, was es braucht, um in der rasanten Welt der Schneckenrennen Fuß zu fassen. Aber Ihr? Ihr schon. Ich weiß einfach, dass Schleimer es genießen wird, Euch den Rest seiner schnecklichen Tage auf Euren Abenteuern zu begleiten.\n\n<Briggul schnieft und streichelt Schleimers Haus.>\n\nHinterlasse deine Schleimspuren auf der Welt, Großer. Und denk daran, mich hin und wieder mal zu besuchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75600] = { id = 75600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidige Seide", description = "Wir haben hier oben zwar keinen Zugriff auf all die schicken Pflanzenfasern, die Ihr Oberländer verwendet, aber dafür haben wir viele Möglichkeiten, die Ihr vermutlich nicht habt!\n\nDie Spinnen in der Nähe von Loamm machen Seide, die faszinierender riecht als alles, was ich je gerochen habe. Vielleicht hat es etwas mit ihrer Ernährung zu tun?\n\nWenn Ihr etwas davon sammelt, wird Rossmar in Loamm Euch sicher die ein oder andere Sache zeigen, die man damit anstellen kann!", sourceObjective = "Sammelt 8 Kalkseidenbündel.", progress = "Folgt einfach den knochigen Gerüchen!", completion = "Verpasst das Kalzium ihr nicht einfach eine tolle Beschaffenheit?", sourceObjectiveStatus = "unverified-source-field" }
quests[75602] = { id = 75602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitterfaser knackt", description = "Die kristallinen Kreaturen zu Hause sind so geheimnisvoll wie stampfig.\n\nWie können sie sich bewegen? Sind sie wirklich lebendig? Und wie schmecken sie?\n\nBringt Fanilly einige Proben, dann können wir damit beginnen, sie zu studieren. Aber keine, die groß genug sind, um in Loamm auf jemanden zu treten, ja?", sourceObjective = "Sammelt 10 lebende Splitter.", progress = "Wer weiß, was wir lernen könnten?", completion = "Faszinierend, {name}. Danke für Euren Beitrag zur Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[75603] = { id = 75603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angemessene Riten", description = "Dieses Mädel ist seit langer, langer Zeit hier. Es ist ein Wunder, dass sie in so gutem Zustand ist.\n\nEs ist eine Sache, Tonscherben aus dem Matsch zu klauben, aber so etwas hier erfordert mehr Sorgfalt und Erfahrung, als wir beide gemeinsam haben! Maruukai ist nicht weit von hier...\n\nWir sollten den Zentauren hiervon erzählen. Dann können die sich entscheiden, wie sie weitermachen wollen, hm?\n\nUnd wo wir schon dabei sind, ich könnte wetten, dass uns ein paar ihrer Handwerksexperten mehr über ihre Ausrüstung sagen können.", sourceObjective = "Sprecht mit Geschichtenwahrer Jaru, Hufschmiedin Rondare und Tigari Khan darüber, wie mit dem uralten Leichnam umgegangen werden soll.", progress = "Jetzt haben wir hier eine richtige Grabung!", completion = "Besser geht es nicht, {name}. Neue Kapitel der Geschichte entwickeln sich, ganze Gemeinschaften versammeln sich um einen Fund...\n\nÜber diese Ausgrabung werden sie noch Jahre sprechen!\n\nDa lohnt sich all dieses Rumstapfen im Schlamm, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[75604] = { id = 75604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antiquierte Eskapaden", description = "Also, hier sind zwei Faktoren im Spiel, ja?\n\nWir sollten sorgfältig vorgehen und herausfinden, wen diese Statue dargestellt hat. Aber unter uns? Mich interessieren viel mehr die Spaßvögel, die es zu dem Kunstwerk gemacht haben.\n\nIch bin sicher, dass es im schwarzen Drachenschwarm irgendwo in Aberrus einen Historiker gibt. Und warum hört Ihr Euch nicht in Loamm um, ob es irgendwelche Geschichten über diese Art von... künstlerischer Ausdrucksweise gibt?", sourceObjective = "Findet Experten in Loamm und im schwarzen Drachenschwarm, die etwas zu Eurem Fund sagen können.", progress = "<Roska scheint mit Eurer Arbeit zufrieden zu sein.>", completion = "Wir müssen weiter um den Turm herum graben.\n\nDa gibt es noch eine Menge Müllschichten zu durchwühlen. Auch wenn wir nicht wieder etwas derart Spektakuläres finden, können wir hier eine Menge über die Niffen lernen und wie sie lebten, bevor und während die Drachen gingen.\n\nAber ich glaube, vorerst haben wir unser Tagwerk erledigt!", sourceObjectiveStatus = "unverified-source-field" }
quests[75608] = { id = 75608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Titanenmüll ist des anderen Titanenschatz", description = "Die Hüter haben allerlei verblüffende Technologien rumliegen lassen, als sie ihren Schlaf angetreten sind.\n\nWir könnten so viel von ihren uralten ausrangierten Teilen lernen. Selbst ihre kleinsten Vorrichtungen sind erstaunlich!\n\nGäbe es doch nur jemanden, der mutig, intelligent und, ich wage zu sagen, gutaussehend genug ist, um unseren besten Niffeneuren in Loamm ein paar Exemplare zur Untersuchung zu bringen... Klingt das vertraut?", sourceObjective = "Sammelt 10 hololithische Getriebe.", progress = "Ich frage mich, ob wir ihre Technologie je wirklich verstehen werden...", completion = "Ihr wollt wissen, was ein hololithisches Getriebe ist? Keine Ahnung, aber ich freue mich schon, es herauszufinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75611] = { id = 75611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerfischer" }
quests[75612] = { id = 75612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Kaskaden" }
quests[75617] = { id = 75617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer auf den Ebenen von Ohn'ahra.", completion = "Ehrt die Flamme der Ebenen von Ohn'ahra.", sourceObjectiveStatus = "unverified-source-field" }
quests[75619] = { id = 75619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Viecher" }
quests[75620] = { id = 75620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lügen im Lichte" }
quests[75621] = { id = 75621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementgeflüster" }
quests[75622] = { id = 75622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An alle Wettkämpfer!", description = "Das Handwerkerkonsortium hat eine Abmachung mit den Rüstmeistern in der Zuflucht des Gladiators getroffen!\n\nZusätzlich zu der üblichen mächtigen Kampfausrüstung, die sie anbieten, können würdige Kämpfer nun Marken kaufen, die sie in Handwerksaufträgen oder bei eigenen Herstellungsverfahren einsetzen können, um die Ausrüstung zur Verwendung auf Schlachtfeldern und in Arenen zu zertifizieren!\n\nZeigt dieses Flugblatt Calderax, um zwei kostenlose Trophäen der Eroberung zu erhalten, aufs Haus!\n\n- Rabul", sourceObjective = "Bringt das Flugblatt zu Calderax in der Zuflucht des Gladiators von Valdrakken.", completion = "Hm, sie wissen jedenfalls, wie sie ihre Zielgruppe erreichen.\n\nHier sind Eure Trophäen, wie versprochen. Verwendet sie, wenn Ihr Ausrüstung herstellt oder Handwerksaufträge vergebt, dann wird die Macht der Ausrüstung vergleichbar zu dem sein, was ich anzubieten habe. Perfekt, wenn Ihr nach etwas hochgradig Spezifischem oder nach etwas mit besonderen Verzierungen sucht... und bereit seid, etwas zusätzliche Arbeit reinzustecken.\n\nFragen? Dann meldet Euch beim Handwerkermarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[75624] = { id = 75624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Champions" }
quests[75625] = { id = 75625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollt Ihr ein Spiel spielen?", description = "<Ihr öffnet eine gekritzelte Notiz.>\n\nHallo, <Kollege/Kollegin>! Ich bin Mizzen, und wie man hört, seid Ihr gut im Finden von Dingen.\n\nWisst Ihr, ich spiele in letzter Zeit immer dieses neue Spiel namens Warcraft Rumble, aber mir sind die Münzen ausgegangen.\n\nWarum treffen wir uns nicht? Dann sage ich Euch, wo man welche findet.", sourceObjective = "Sprecht mit Mizzen im Hafen von Sturmwind.", completion = "Hallo, schön, dass Ihr es geschafft habt.\n\nIhr müsst Euch diesen Automaten anschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75626] = { id = 75626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollt Ihr ein Spiel spielen?", description = "<Ihr öffnet eine gekritzelte Notiz.>\n\nHallo, <Kollege/Kollegin>! Ich bin Mizzen, und wie man hört, seid Ihr gut im Finden von Dingen.\n\nWisst Ihr, ich spiele in letzter Zeit immer dieses neue Spiel namens Warcraft Rumble, aber mir sind die Münzen ausgegangen.\n\nWarum treffen wir uns nicht? Dann sage ich Euch, wo man welche findet.", sourceObjective = "Sprecht mit Mizzen im Tal der Stärke in Orgrimmar.", completion = "Hallo, schön, dass Ihr es geschafft habt.\n\nIhr müsst Euch diesen Automaten anschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75632] = { id = 75632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verlorene Scheibe", description = "Als ein Zeichen des guten Willens versprach Eternus ihre Unterstützung bei der Suche nach der Scheibe mit Tyrs Erinnerungen. Die Ewigen besitzen Geräte, die bei der Weissagung ihrer Position helfen können.\n\nUm Eternus zu zitieren: \"Deios hat dieses Chaos zu verantworten. Es ist nur gerecht, dass wir bei seiner Bereinigung helfen.\"\n\nIch fühle mich ebenfalls verantwortlich, nach unserem Versuch, Tyr mit der Silberschuppe zu wecken.\n\nTrefft Eternus in Tyrhold. Sie wird Euch auf den neuesten Stand bringen. Vielleicht wird unsere alte Freundin sich uns endlich wieder anschließen.", sourceObjective = "Trefft Eternus in Tyrhold.", completion = "Wir werden uns wiedersehen, {name}. Nozdormu sagte, Ihr würdet kommen. Eure Hilfe ist willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75633] = { id = 75633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Technologie", description = "Während unserer... langen Diskussion darüber, wie wir Tyrs Scheibe finden wollen, sind Chromie und ich zu der Übereinstimmung gekommen, dass Ihr genau die Person seid, die uns helfen kann, {name}. Aber die Position von Tyrs Scheibe herauszufinden, könnte gefährlich werden und erfordert sehr wahrscheinlich mehr als nur Eure Hilfe.\n\nChromie kann Euch mehr erklären, während ich hier daran arbeite, einzugrenzen, was wir brauchen, um die Scheibe zu finden.", sourceObjective = "Fragt Chromie nach dem Plan, Tyrs Erinnerungsscheibe zurückzuholen.", completion = "Es tut gut, Euch wiederzusehen, {name}! Ich hoffe, dass wir Tyrs Erinnerungen diesmal wirklich wiederherstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[75634] = { id = 75634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Wache neu schmieden", description = "Nachdem das Grab zerstört wurde und die Silberschuppe Tyr nicht zurückbringen konnte, habe ich die Entscheidung getroffen, mein Leben nun Tyr zu widmen.\n\nUnd ich habe die noch viel schwierigere Entscheidung getroffen, meine Vergangenheit hinter mir zu lassen und Tyrs Wache neu zu schmieden.\n\nIch habe daran geglaubt, dass Tyr mich bald wieder brauchen würde. Und nachdem wir uns mit der Silbernen Hand beraten haben, glauben Koranos und ich, dass wir vier würdige Rekruten für Tyrs Wache gefunden haben.\n\nKommt mit mir zur Brackenfellhöhle und unterstützt mich bei ihrem abschließenden Training. Dann können wir in die Zeitwege aufbrechen, um Tyrs Scheibe zu finden!", sourceObjective = "Trefft Travard im Lager von Tyrs Wache in der Brackenfellhöhle.", completion = "Jetzt, wo Ihr hier seid, können wir mit den letzten Prüfungen meiner Rekruten anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75635] = { id = 75635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Tyr!", description = "Haben sie alle ihre Prüfungen erfolgreich abgeschlossen? Gut. Ich bin sicher, Ihr hattet keinen geringen Anteil daran.\n\nEs gibt einen letzten Schritt, den wir machen müssen, bevor wir unsere Rekruten offiziell als vollwertige Mitglieder von Tyrs Wache einweihen können: die Initiationszeremonie von Tyrs Wache.\n\nIch wäre stolz, wenn Ihr mit uns auf den Stufen von Tyrhold stehen könntet, während ich Tyrs Wache offiziell neu schmiede. Würdet Ihr uns die Ehre erweisen?", sourceObjective = "Erlebt die Einweihungszeremonie von Tyrs Wache auf den Stufen von Tyrhold mit.", completion = "Tyrs Wache erhebt sich einmal mehr. Ich fühle mich erneuert und... sehr alt. Sie haben noch viel zu lernen und ich habe ihnen viel beizubringen.\n\nNun denn, widmen wir uns der Wiedererweckung von Tyrs Erinnerungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75636] = { id = 75636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrangulation", description = "Die Portale sind bereit. Je eher Euer Team die Leuchtfeuer platziert, umso eher können wir die Position der Scheibe feststellen.\n\nWie Ihr Eure Streitkräfte einsetzt, liegt bei Euch und Travard.", sourceObjective = "Beschützt Travard beim Tempel der Ordnung.", completion = "Willkommen zurück! Eternus sagte, es gäbe ein Signal von Eurem Leuchtfeuer, es lief also alles nach Plan?", sourceObjectiveStatus = "unverified-source-field" }
quests[75637] = { id = 75637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Leuchtfeuer", description = "Valunei und Talthis sind immer noch nicht zurück. Sie müssen Schwierigkeiten mit ihrem Leuchtfeuer haben. Ohne es können wir die Scheibe nicht finden und von hier können wir ihnen nicht helfen.\n\nWir müssen Tyrs Wache durch ihr Portal führen, um zu helfen. Seid Ihr bereit, {name}?", sourceObjective = "Helft Tyrs Wache, das letzte Leuchtfeuer zu aktivieren.", progress = "Wir müssen herausfinden, was passiert ist.", completion = "Wie sind alle wohlbehalten zurück, dem Licht sei Dank.\n\nNun können unsere Drachenfreunde hoffentlich diese Scheibe finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75638] = { id = 75638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwundene Scheibe gefunden", description = "Wir waren erfolgreich, {name}, aber wir haben den Kampf gegen das Schwarze Imperium gerade so überstanden.\n\nEternus sucht immer noch die Position der Scheibe. Und währenddessen möchte ich Euch um einen Gefallen bitten.\n\nIch habe starkes Vertrauen in meine Rekruten, aber...\n\nIch mache mir Sorgen um Valunei. Ich würde mit ihr sprechen, aber es soll nicht aussehen, als wäre ich enttäuscht von ihr. Sprecht mit ihr und stellt sicher, dass es ihr gut geht.\n\nVielleicht wäre es auch eine gute Idee, ebenfalls nach den anderen von Tyrs Wache zu sehen.", sourceObjective = "Seht nach Tyrs Wache.", progress = "Ich mache mir Sorgen um meine Rekruten, aber möglicherweise sollte ich mir auch um mich selbst Sorgen machen.\n\nTyrs Wache neu zu formieren, war eine Art Läuterung. Aber ich befürchte, dass es derer zu viel sein könnte.\n\nIch war über den Verlust meiner Kameraden in Tyrs Wache am Boden zerstört... Es besteht die Gefahr, dass ich sie vielleicht zu sehr unter Druck setze.\n\nOder mich selbst... Ich bin schon so lange dabei, {name}. Aber Tyr wieder lebendig zu sehen... Das verleiht mir Mut.\n\nIch hoffe nur, dass ich mit dem Alter weiser werde und meine neuen Rekruten richtig behandle. Und dass sie alle wieder heimkehren.", completion = "Ich bin froh zu hören, dass Ihr mit ihr sprechen konntet. Klingt, als wäre sie wirklich bereit, trotz allem, was passiert ist.\n\nNicht jeder wäre nach all dem wieder auf die Beine gekommen, aber Valunei ist stärker, als vielen von uns klar ist.\n\nSobald Eternus die Scheibe gefunden hat, werden wir bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[75639] = { id = 75639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflischer Argwohn", sourceObjective = "Spioniert Madame Schatten und Assistent Phineas auf dem Dunkelmond-Jahrmarkt nach.", completion = "Der Tor fühlt sich warm an.", sourceObjectiveStatus = "unverified-source-field" }
quests[75640] = { id = 75640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer im Azurblauen Gebirge.", completion = "Ehrt die Flamme des Azurblauen Gebirges.", sourceObjectiveStatus = "unverified-source-field" }
quests[75641] = { id = 75641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Macht", description = "Unsere Erkundung ist vom Glück geküsst, {name}! Wir haben etwas gefunden, dass Euch weiterhelfen könnte.\n\nEs ist eine Hälfte eines Funken der Schattenflamme. Es ist leider nur ein Splitter und alleine nicht sonderlich mächtig, doch wenn Ihr die andere Hälfte findet und sie vereint, könnte der Funke sich als mächtiges Reagenz für Euer Handwerk herausstellen.\n\nFindet einen weiteren gesplitterten Funken der Schattenflamme. Vereint die beiden Teile, um ihr volles Potenzial zu entfesseln.", sourceObjective = "Findet einen weiteren gesplitterten Funken der Schattenflamme.", progress = "Habt Ihr die andere Hälfte des Funken gefunden?", completion = "Ausgezeichnet! Wenn Ihr weitere gesplitterte Funken findet, dann vereint sie, um Eure Handwerkswaren zu verbessern!", sourceObjectiveStatus = "unverified-source-field" }
quests[75643] = { id = 75643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Niffen von Loamm", description = "Ich bin beeindruckt. Älteste Honigpelz spricht in höchsten Tönen von Euch, und das passiert selten!\n\nZugegebenermaßen haben Eure Freunde Ebyssian und Glutthal in die gleiche Kerbe geschlagen, nachdem wir ihre Fährte aufgenommen hatten. Sie berichteten mir von Eurer Jagd auf das Feuermonster vom Oberland, das in Zaralek eingefallen ist. Ein würdiger Grund, sich zu verbünden.\n\nAber wir brauchen ein bisschen mehr Zeit, um alles gemeinsam zu besprechen. Legt eine kurze Pause ein und lernt mein Volk kennen. Ob Handel, Freizeit oder Reisen, hier in Loamm gibt es jede Menge Möglichkeiten, um Zeit zu verbringen!", sourceObjective = "Trefft den Flugmeister in Loamm.", completion = "Die Zaralekhöhlen werden noch länger unter diesen neuen Feinden leiden müssen, also sollten wir uns mit offenen Armen und Schnauzen kennenlernen.\n\nBetrachtet dies als Eure offizielle Einladung, bei uns zu verweilen in Loamm, der großen Stadt der Gerüche!", sourceObjectiveStatus = "unverified-source-field" }
quests[75644] = { id = 75644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief unter der Erde", description = "Das war nur ein Vorgeschmack auf die Lebensweise der Niffen. Loamm hat noch vieles mehr zu bieten, und die Zaralekhöhle erst recht. Setzt Eure Erkundung fort, während Ihr das Feuermonster verfolgt, und lasst Euch immer wieder aufs Neue von seinen Gerüchen überraschen!\n\nZunächst hat mich Ebyssian gebeten, Euch zu ihm schicken. Es scheint so, als würden Eure Gefährten überlegen, was als Nächstes zu tun ist.", sourceObjective = "Besprecht den nächsten Aktionsplan mit Ebyssian.", completion = "Ich wünschte zwar immer noch, Ihr hättet auf Glutthal und mich gewartet, aber das Ergebnis wäre wohl nicht anders ausgefallen. Diese Inkarnation ist mächtiger, als wir erwartet haben.\n\nWir müssen viel bedenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[75645] = { id = 75645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in Thaldraszus.", completion = "Ehrt die Flamme von Thaldraszus.", sourceObjectiveStatus = "unverified-source-field" }
quests[75647] = { id = 75647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer auf der Verbotenen Insel.", completion = "Ehrt die Flamme der Verbotenen Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[75650] = { id = 75650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Zaralekhöhle.", completion = "Ehrt die Flamme der Zaralekhöhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[75657] = { id = 75657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitverlorenes Trio", description = "Wir haben ein kleines Problemchen, bei dem ich Eure Hilfe brauchen könnte. Es ist allerdings... kompliziert.\n\nVor einer Weile war König Varian Wrynn Teil eines Gladiatorentrios, gemeinsam mit Broll Bärenfell und Valeera Sanguinar. Diese drei sind gerade auf diesem \"Feld der Wildheit\" aufgetaucht und stellen sich nicht nur allen Herausforderern, sondern schlagen sie auch noch! Sie kehren nicht durch unsere Portale zurück, bis sie verlieren!\n\nKönntet Ihr vielleicht einige Freunde finden und sie besiegen? Dann werden wir sie überzeugen können, zurückzugehen, da bin ich sicher!", sourceObjective = "Besiegt Valeera, Broll und Lo'Gosh.", progress = "Ihr müsst mit Gurgthock sprech'n, um die Runde zu beginn'. Besiegt dann die zeitverlor'nen Gladiatoren.", completion = "Hm. Ich hab gar nich' gewusst, dass wir 'ne solche Gruppe auf dem Plan hatten. Oder glitzerndes gold'nes Feuerwerk.\n\nAber Ihr habt wohl gewonn', also hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[75660] = { id = 75660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende ihrer Wacht" }
quests[75661] = { id = 75661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilende Kristallsammlung" }
quests[75662] = { id = 75662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Zielgeraden", description = "Ihr seht mir wie jemand aus, der ein gutes Schneckenrennen zu schätzen weiß! \n\nAber was macht ein Schneckenrennen gut, fragt Ihr Euch? Jede Schnecke muss eine Chance darauf haben, das Rennen zu gewinnen! \n\nUnd manchmal brauchen die Schnecken vielleicht etwas Hilfe. \n\nWenn Ihr Euch vom Chefkoch einen Beutel mit Leckerlis schnappt und sie ihnen in die Bahn werft, setzt sie das in Bewegung. \n\nWie wäre es, wenn wir Schüchti ein bisschen zum Sieg verhelfen?", sourceObjective = "Helft Schüchti, ein Rennen zu gewinnen.", progress = "Hat Eure Schnecke das Rennen gewonnen?", completion = "Was für ein Sieg! Ich finde, Ihr solltet Schüchtis neuer Trainer werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75663] = { id = 75663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhelose Qualen" }
quests[75664] = { id = 75664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonische Kristalle" }
quests[75665] = { id = 75665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiger Verbündeter: Die Niffen von Loamm", description = "Djaradin, Dracthyr und Drachen! Oje! Die Gefahren in dieser Höhle sind kaum zu überriechen. Wir könnten etwas bewaffnete Unterstützung brauchen.\n\nTut mir einen Gefallen, dann stelle ich sicher, dass die Sippe den Gefallen erwidert! Wir haben haufenweise gutes Zeug... für das richtige Klientel.\n\nWas sagt Ihr? Wollt Ihr da raus und unsere Konkurrenz begraben?", sourceObjective = "Helft den Niffen und ihren Verbündeten in der Zaralekhöhle.", progress = "Schauen sich unsere Feinde die Radieschen von unten an?", completion = "Ihr seid ein gutes Stück näher daran, das gute Zeug zu riechen zu bekommen.\n\nIhr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[75667] = { id = 75667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßigkeiteneimer", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[75668] = { id = 75668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßigkeiteneimer", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
