quests[75694] = { id = 75694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, Schmelztiegel der Schatten: Sarkareth", description = "Ich habe kein Interesse daran, meinen Brüdern nach Aberrus zu folgen, doch ich mache mir weiterhin Sorgen um ihr Wohlergehen. Neltharion ist dem Wahnsinn so sehr anheimgefallen, dass seine geheime Festung zweifellos mit zahllosen, unvorstellbaren Gefahren gefüllt ist.\n\nGeht mit ihnen, {name}. Steht ihnen zur Seite. Sie werden bei dem, was sie dort erwartet, Eure Hilfe brauchen.", sourceObjective = "Betretet Aberrus, Schmelztiegel der Schatten, und besiegt Sarkareth.", completion = "Ich hätte nie gedacht, dass Sarkareth so weit gehen würde, um Macht zu erlangen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
