quests[75706] = { id = 75706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Zielgeraden", description = "Jeder liebt ein gutes Schneckenrennen! Die spannendsten Rennen sind die, bei denen alle Schnecken eine Chance auf den Sieg haben.\n\nIhr könnt einer Schnecke dabei helfen, zu gewinnen, indem Ihr ihr Leckerlis gebt. Schaut, wie schnell sie dadurch werden!\n\nSchnappt Euch einen Beutel mit Leckerlis und werft sie den Schnecken in die Bahn. Versucht, Tricksi dabei zu helfen, zu gewinnen!", sourceObjective = "Helft Tricksi, ein Rennen zu gewinnen.", progress = "Hat Eure Schnecke das Rennen gewonnen?", completion = "Was für ein Sieg! Ich finde, Ihr solltet Tricksis neuer Trainer werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75707] = { id = 75707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Zielgeraden", description = "Jeder liebt ein gutes Schneckenrennen! Die spannendsten Rennen sind die, bei denen alle Schnecken eine Chance auf den Sieg haben.\n\nIhr könnt einer Schnecke dabei helfen, zu gewinnen, indem Ihr ihr Leckerlis gebt. Schaut, wie schnell sie dadurch werden!\n\nSchnappt Euch einen Beutel mit Leckerlis und werft sie den Schnecken die Bahn. Versucht, Brulee dabei zu helfen, zu gewinnen!", sourceObjective = "Helft Brulee, ein Rennen zu gewinnen.", progress = "Hat Eure Schnecke das Rennen gewonnen?", completion = "Was für ein Sieg! Ich finde, Ihr solltet Brulees neuer Trainer werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75709] = { id = 75709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble-Münze finden", description = "Um diesen Spielautomaten zu verwenden, benötigt Ihr eine Rumble-Münze.\n\nAuf den Dracheninseln sind mehrere davon versteckt. Darüber können wir allerdings später sprechen.\n\nIch habe hier an den Docks eine Münze versteckt. Wenn Ihr sie findet, gehört sie Euch.\n\nWerft die Rumble-Münze in den Rumble-Automaten und lasst den Spaß beginnen!", sourceObjective = "Findet eine Rumble-Münze im Hafen von Sturmwind und werft sie in den Warcraft Rumble-Automaten.", progress = "<Der Warcraft Rumble-Automat steht vor Euch. Auf einem kleinen Schild steht:>\n\nZum Spielen Rumble-Münze einwerfen.", completion = "<Als Ihr die Münze einwerft, beginnt der lustige, kleine Automat zu poltern und zu klimpern.\n\nIhr habt einen Preis gewonnen!>", sourceObjectiveStatus = "unverified-source-field" }
quests[75711] = { id = 75711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble-Münze finden", description = "Um diesen Spielautomaten zu verwenden, benötigt Ihr eine Rumble-Münze.\n\nAuf den Dracheninseln sind mehrere davon versteckt. Darüber können wir allerdings später sprechen.\n\nIch habe drüben im Gasthaus eine Münze versteckt. Wenn Ihr sie findet, gehört sie Euch.\n\nWerft die Rumble-Münze in den Rumble-Automaten und lasst den Spaß beginnen!", sourceObjective = "Findet eine Rumble-Münze im Gebrochenen Hauer und werft sie in den Warcraft Rumble-Automaten.", progress = "<Der Warcraft Rumble-Automat steht vor Euch. Auf einem kleinen Schild steht:>\n\nZum Spielen Rumble-Münze einwerfen.", completion = "<Als Ihr die Münze einwerft, beginnt der lustige, kleine Automat zu poltern und zu klimpern.\n\nIhr habt einen Preis gewonnen!>", sourceObjectiveStatus = "unverified-source-field" }
quests[75712] = { id = 75712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warcraft Rumble-Miniaturen: Neues Aussehen!", description = "<Ihr entdeckt eine in die Folie geritzte Botschaft.>\n\nDiese Warcraft Rumble-Folie kann an einem Warcraft Rumble-Automaten verwendet werden. Verschafft einer Eurer Miniaturen ein neues Aussehen!", sourceObjective = "Geht zum Warcraft Rumble-Automaten im Hafen von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[75713] = { id = 75713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warcraft Rumble-Miniaturen: Neues Aussehen!", description = "<Ihr entdeckt eine in die Folie geritzte Botschaft.>\n\nDiese Warcraft Rumble-Folie kann an einem Warcraft Rumble-Automaten verwendet werden. Verschafft einer Eurer Miniaturen ein neues Aussehen!", sourceObjective = "Geht zum Warcraft Rumble-Automaten im Tal der Stärke in Orgrimmar.", completion = "<Der Warcraft Rumble-Automat hat eine Öffnung. Sie hat genau die richtige Größe, um eine Miniatur und eine Warcraft Rumble-Folie einzulegen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75720] = { id = 75720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tausch gefällig?", description = "Hallo, <Oberländer/Oberländerin>!\n\nIch hörte, Ihr helft gern. Vielleicht könnt Ihr mir helfen? \n\nIch muss ein paar Pakete nach Valdrakken schicken. Wenn Ihr nicht reinschaut und keine Fragen stellt, wird es die Sache wert sein. \n\nKommt vorbei, wenn Ihr in Loamm seid. Dann einigen wir uns schon!\n\nEuer neuer Freund, Ponzo.", sourceObjective = "Sprecht mit Ponzo in Loamm.", completion = "Ich kann meinen Brief an Euch riechen. Wollt Ihr aushelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[75721] = { id = 75721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundlagen des Tauschhandels", description = "Gut, Ihr müsst folgendes für mich tun. \n\nEin Freund von mir, Kayann, ist bis hinauf nach Valdrakken gegangen. Er erwartet eine Lieferung von mir. Könnt Ihr sie ihm bringen? \n\nAber keine Fragen. Nicht schauen, nicht riechen, nicht kosten. Das ist allein für Kayanns Nase!\n\nWenn Euch das nicht stört, schicke ich Euch los. Und danke Euch natürlich!", sourceObjective = "Bringt Ponzos Paket zu Kayann in Valdrakken.", completion = "Ich weiß, dass es ein Paket von Ponzo ist, wenn ich es rieche!\n\nDanke für die Lieferung, das war eine lange Reise! Hier ist etwas, das Ponzo ganz sicher liebend gern eintauschen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[75722] = { id = 75722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tasche voller Gold", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Wir werden Euch ewig dankbar sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[75723] = { id = 75723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenbeobachtung in Höhlen", description = "Ach, hallo, <Oberländer/Oberländerin>!\n\nEs spricht sich herum, dass Ihr uns wirklich helft! Wir haben als Gegenleistung eine Kleinigkeit für Euch. Trefft mich in Loamm, dann gebe ich sie Euch!\n\nGrüße, \nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", completion = "Es ist gut, Euch hier zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[75724] = { id = 75724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Niffen", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Zieht diese Fäustlinge an, rein damit in die Erde, macht die Nase auf und... Bumm!\n\nMan riecht Loamm von überall in der Zaralekhöhle. \n\nDas Geheimnis sind die Klauen! Das waren sie immer schon!", sourceObjectiveStatus = "unverified-source-field" }
quests[75725] = { id = 75725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Bahn", description = "Hey, Champion! \n\nWir haben eine neue goldene Gelegenheit für Euch. Schneckenrennen! Eine der rasantesten Sportarten überhaupt! \n\nPonzo sagte, Ihr wäret interessiert. Nannte Euch voller Tatendrang!\n\nAlso los! Trefft mich auf der Strecke in Glimmerogg! \n\nBis dann, \nBriggul", sourceObjective = "Sprecht mit Briggul in Glimmerogg.", completion = "Da seid Ihr ja! Jetzt müssen wir nur noch... unsere Schnecke trainieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[75726] = { id = 75726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweißnasse Rüstung", description = "Hallo, <mein Lieber/meine Liebe>! \n\nEure fortwährende Unterstützung spricht sich rum! Wir haben ein paar Rüstungsteile gefunden, die Euch helfen sollten, um Euch für Eure Hilfe zu danken. \n\nKommt unbedingt in Loamm vorbei, damit wir uns um Euch kümmern können. \n\nGrüße, \nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[75727] = { id = 75727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der duftigste Wappenrock", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Hier ist er, handgemacht und handbeduftet!", sourceObjectiveStatus = "unverified-source-field" }
quests[75728] = { id = 75728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauschfelsbrocken", description = "Oh, hallo, <Oberländer/Oberländerin>! Ich könnte noch mal Eure Hilfe brauchen. \n\nAber hier geht es nicht um kleine Ziegel. Die sind nutzlos. Jetzt heißt es \"ran an die Felsbrocken\"! \n\nTrefft mich in Loamm, dann erzähle ich Euch alles weitere.\n\nPonzo", sourceObjective = "Sprecht mit Ponzo in Loamm.", completion = "Ich hoffe, Ihr habt trainiert. Die hier sind alles andere als leicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[75729] = { id = 75729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf den Beobachter", description = "Könnt Ihr es fassen, dass dies mal eine Sternwarte war? Den Aufzeichnungen zufolge haben die Drachkin hier Himmelskörper verfolgt und so versucht, die Zukunft vorherzusagen.\n\nWie haben sie es wohl gemacht, was meint Ihr?\n\nIch empfange eine Teilsignatur, die zu dem Zeitfenster passt, nach dem wir suchen. Setzt den Technoseher auf und versucht, die Quellen zu finden, damit wir alles einstellen können.", sourceObjective = "Findet mit dem Technoseher die drei Abstimmungsrelikte.", progress = "Ohne diese Abstimmungsrelikte werden wir das Geheimnis nicht lösen können, {name}.", completion = "Aha! Gebt mir Euren Seher, damit ich ihn kalibrieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[75730] = { id = 75730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriecherdrachenbeobachtung", description = "Ah, hallo!\n\nEs spricht sich herum, dass wir Eure anhaltende Unterstützung haben. Darum haben wir da etwas für Euch. Trefft mich in Loamm, damit ich es Euch geben kann!\n\nGrüße,\nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", completion = "Es ist gut, Euch hier zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[75731] = { id = 75731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duftende Stiefel", description = "Ah, hallo!\n\nEure anhaltende Unterstützung spricht sich herum. Wir haben eine Rüstung gefunden, die Ihr vielleicht gebrauchen könnt. Treff mich in Loamm, dann finden wir heraus, ob es zu etwas nutze ist!\n\nGrüße,\nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", completion = "Wir sind froh, Euch hier zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75741] = { id = 75741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschiedene Felsbrocken", description = "He, <Oberländer/Oberländerin>!\n\nIch hörte, Ihr habt herumerzählt, dass ich nicht nett zu Euch war. \n\nDas stimmt nicht, aber sie sagten mir, ich soll netter zu Euch sein, weil Ihr so viel für uns getan habt. \n\nIch soll Euch ausgenutzt haben? Ich hab Euch ja wohl ehrliche Arbeit gegeben!\n\nAber um Euch und die anderen zufriedenzustellen, werde ich Euch einige Felsbrocken geben. \n\nTrefft mich in Loamm. \nPonzo", sourceObjective = "Sprecht mit Ponzo in Loamm.", completion = "Und sagt Mimuup auf jeden Fall, dass ich nett zu Euch war, hört Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[75742] = { id = 75742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenhelme", description = "Hallo!\n\nEure anhaltende Unterstützung spricht sich herum. \n\nWir haben da etwas für Euch. Trefft mich in Loamm, damit ich es Euch geben kann!\n\nGrüße,\nHarlowe Marl", sourceObjective = "Sprecht mit Harlowe Marl in Loamm.", completion = "Wir sind froh, Euch hier zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75744] = { id = 75744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen unserer Dankbarkeit", description = "Grüße!\n\nNachdem Ihr uns so viel geholfen habt, dachten wir, dass wir den Gefallen endlich erwidern sollten.\n\nTrefft mich in Loamm. Wir haben eine Belohnung, die wir Euch dringend geben wollen.\n\nHochachtungsvoll,\nMimuup", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Ich danke Euch für alles, Oberländer!", sourceObjectiveStatus = "unverified-source-field" }
quests[75750] = { id = 75750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind sie nicht wunderschön?", sourceObjective = "Besiegt Shinmura in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[75765] = { id = 75765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssige Kunst", description = "<Ein Tontopf gefüllt mit... Dreck?\n\nEr scheint von den Niffen zu stammen. Vielleicht sucht ein Bewohner von Loamm nach ihm!>", sourceObjective = "Bringt den tropfenden Tontopf zu seinem Besitzer in Loamm zurück.", progress = "Oh, ist das...?", completion = "Ihr habt meinen liebsten Schlicktopf gefunden!\n\nIch kann in jedem Topf Schlick machen, aber das ist einer der ersten Töpfe, die ich aus speziellen, selbst ausgegrabenen Sedimenten gemacht habe.\n\nEr hat sentimentalen Wert... UND sedimentalen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75766] = { id = 75766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edler Edelstein", description = "<Ein herrlicher, in feines Gold gefasster Rubin liegt in einem Kästchen drakonischen Ursprungs.\n\nDie Juwelenschleiferin in Loamm würde sicher gerne einen Blick darauf werfen.>", sourceObjective = "Bringt den schimmernden drakonischen Edelstein zu Fanilly in Loamm.", progress = "Oh, wie der glänzt!", completion = "Ist der herrlich! Haben Drachen den gemacht? Er ist so rot und glitzernd!\n\nIch danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[75767] = { id = 75767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzen macht glücklich", description = "<Ein sehr nasses Gorloctotem liegt auf dem Höhlenboden. Wie ist das überhaupt hierhergekommen?\n\nDie Niffen lieben solche Dinger, vielleicht nimmt jemand in Loamm Euch das ab.>", sourceObjective = "Findet ein neues Zuhause für das durchnässte Totem in Loamm.", progress = "Ich brauchte Tanzverstärkung!", completion = "<Der Niffen schnüffelt intensiv an dem Totem.>\n\nEr riecht nach Fisch! Das ist sehr gut!\n\nDer gibt einen perfekten Türsteher für meine Auftritte ab. Ich glaube, ich nenne ihn... Pfeifer!", sourceObjectiveStatus = "unverified-source-field" }
quests[75768] = { id = 75768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücksentchen", description = "<Ihr findet ein kleines Spielzeugentchen.\n\nEs erinnert Euch ein kleines bisschen an die Schwalben von Loamm. Vielleicht gefällt es ja Zimto?>", sourceObjective = "Gebt den gefiederten Freund Zimto in Loamm.", progress = "Für mich?", completion = "Oh, danke, {name}.\n\nAls neuer leitender Schwalbenpfleger kann ich einen Lehrling gut brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75769] = { id = 75769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere Leinwand", description = "<Eine weggeworfene und mit Staub bedeckte Leinwand liegt auf dem Höhlenboden.\n\nVielleicht hat jemand in Loamm Verwendung dafür?>", sourceObjective = "Gebt das gespannte Segeltuch einem Niffen in Loamm.", progress = "Woher wusstet Ihr, dass ich es mal mit Geruchsmalerei versuchen will?", completion = "Eine nagelneues Segeltuch! Ich kann das als Leinwand verwenden und mich an der Geruchsmalerei versuchen.\n\nJetzt riecht sie ja noch so... leer! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[75770] = { id = 75770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubbernde Spezialität", description = "<Ihr findet einen blau leuchtenden Trank unbestimmter Herkunft.\n\nVielleicht möchte die Alchemistin von Loamm einen Blick darauf werfen?>", sourceObjective = "Bringt das blubbernde Elixier zu Neblie in Loamm.", progress = "Hmm... Ich muss eine Analyse durchführen!", completion = "Das ist höchst interessant.\n\nIch muss die besten Nasen in Loamm beauftragen, damit wir rausfinden können, was das ist.\n\nDanke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[75771] = { id = 75771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räucherherkunft", description = "<Ihr findet vertraut riechendes Räucherwerk, aber Ihr könnt es nicht zuordnen.\n\nCitros wird unbedingt mal daran schnuppern wollen.>", sourceObjective = "Bringt das mysteriöse Räucherwerk zu Citros in Loamm.", progress = "Oh, du meine Güte! Das nenne ich mal starkes Räucherwerk!", completion = "Das riecht nicht nach Niffen!\n\nEs riecht aber nicht schlecht, überhaupt nicht!\n\nKönnte ich das etwas genauer erschnüffeln, wenn es Euch nichts ausmacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[75772] = { id = 75772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenlieferung", description = "<Eine kleine, mit Leder umhüllte Flasche liegt in der Höhle auf einem Sims.\n\nVielleicht vermisst sie jemand.>", sourceObjective = "Findet den Besitzer der lederumhüllten Flasche.", progress = "Nun, mir gehört sie nicht, aber ich nehme sie Euch ab!", completion = "Das kann auf keinen Fall jemandem in Loamm gehört haben. So ein Leder habe ich noch nie gesehen.\n\nKann ich die mal genauer anschnuppern, wenn Ihr nichts dagegen habt? Vielleicht kann ich einige dieser Techniken anwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[75773] = { id = 75773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines leeres Buch", description = "<Ihr findet ein Buch mit drakonischem Text und nicht viel mehr.\n\nVielleicht könnte jemand in Loamm Euch helfen, es zu entziffern?>", sourceObjective = "Bringt das Buch zurück nach Loamm.", progress = "Was soll ich denn da lesen? Da steht doch nichts drin!", completion = "Da steht nichts drin! Es riecht einfach nur nach leerem Papier!\n\nIch kann es nicht lesen, wenn es nach nichts riecht, Oberländer.\n\nAber danke, dass Ihr mir ein leeres Notizbuch gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
